using System.Linq;
using BlocksBeyondTheStars.Shared.Content;
using BlocksBeyondTheStars.Shared.State;
using Xunit;

namespace BlocksBeyondTheStars.Tests;

/// <summary>The shipped Christmas outfit (#3321, door 12 of the Advent calendar; generated by
/// <c>tools/gen_festive_skins.py</c>): every part fully painted in valid payloads, the player's own skin colour kept, and
/// green, white and gold carrying it — red is the enemies' colour in this game, so it may only be an accent.</summary>
public sealed class ChristmasSkinContentTests
{
    private const string Alphabet = "0123456789abcdefghijklmnopqrstuv";

    // FacePalette indices: green 11 / dark green 26, white 4 / light grey 18, gold 10 / dark orange 24 / light yellow 25,
    // red 8 / dark red 22 / light red 23.
    private static readonly int[] GreenWhiteGold = { 11, 26, 4, 18, 10, 24, 25 };
    private static readonly int[] Reds = { 8, 22, 23 };

    [Fact]
    public void TheChristmasOutfit_PaintsEveryPart_AndKeepsThePlayersSkin()
    {
        var content = ContentLoader.LoadFromDirectory(TestPaths.DataDir());
        content.Validate();
        var skin = content.FindSkin("christmas");
        Assert.NotNull(skin);
        Assert.Equal("calendar", skin!.Unlock);
        Assert.Equal(4, skin.Colors.Length);
        Assert.Equal(string.Empty, skin.Colors[0]); // the face and skin stay the player's own
        Assert.All(skin.Colors.Skip(1), c => Assert.Matches("^#[0-9a-f]{6}$", c));
        Assert.Equal(BodyPaint.PartCount, skin.Paint.Length);
        for (int part = 0; part < BodyPaint.PartCount; part++)
        {
            string pixels = skin.Paint[part];
            Assert.Equal(BodyPaint.ExpectedLength(part), pixels.Length);
            Assert.True(PaintPayload.IsValidSymbols(pixels), $"part {part} uses symbols outside the palette");
            Assert.DoesNotContain('0', pixels); // painted all over — no base colour shows through
        }
    }

    [Fact]
    public void TheChristmasOutfit_IsGreenWhiteAndGold_WithRedOnlyAsAnAccent()
    {
        var skin = ContentLoader.LoadFromDirectory(TestPaths.DataDir()).FindSkin("christmas")!;
        var indices = skin.Paint.SelectMany(p => p).Select(ch => Alphabet.IndexOf(ch)).ToList();
        double Share(int[] palette) => indices.Count(i => palette.Contains(i)) / (double)indices.Count;

        Assert.True(Share(GreenWhiteGold) > 0.7, $"green, white and gold cover only {Share(GreenWhiteGold):P1}");
        Assert.InRange(Share(Reds), 0.0005, 0.02); // there, but only as small accents (buttons, a stripe, a pompom)
    }
}
